<template>
  <div>
    <div style="overflow: auto; margin-right: 30px;">
      <!-- 添加用户按钮 -->
      <el-button style="float: right;" @click="handleAddUserClick">添加用户</el-button>
    </div>
    <!-- 用户列表 -->
    <el-table :data="users" stripe>
      <el-table-column prop="id" label="ID"></el-table-column>
      <el-table-column prop="name" label="姓名"></el-table-column>
      <el-table-column prop="email" label="邮箱"></el-table-column>
      <el-table-column label="操作">
        <template #default="scope">
          <el-button size="mini" @click="editUser(scope.row)">编辑</el-button>
          <el-button size="mini" type="danger" @click="deleteUser(scope.row.id)">删除</el-button>
        </template>
      </el-table-column>
    </el-table>

    <el-dialog v-model="showAddUserDialog" title="添加用户">
      <template #content>
        <el-form ref="addForm" :model="newUser" label-width="80px">
          <el-form-item label="姓名">
            <el-input v-model="newUser.name"></el-input>
          </el-form-item>
          <el-form-item label="邮箱">
            <el-input v-model="newUser.email"></el-input>
          </el-form-item>
        </el-form>
      </template>
      <template #footer>
        <span class="dialog-footer">
          <el-button @click="showAddUserDialog = false">取消</el-button>
          <el-button type="primary" @click="addUser">确定</el-button>
        </span>
      </template>
    </el-dialog>

    <!-- 编辑用户对话框 -->
    <el-dialog v-model="showEditUserDialog" title="编辑用户">
      <template #content>
        <el-form :model="editedUser" label-width="80px">
          <el-form-item label="姓名">
            <el-input v-model="editedUser.name"></el-input>
          </el-form-item>
          <el-form-item label="邮箱">
            <el-input v-model="editedUser.email"></el-input>
          </el-form-item>
        </el-form>
      </template>
      <template #footer>
        <span class="dialog-footer">
          <el-button size="small" @click="showEditUserDialog = false">取消</el-button>
          <el-button size="small" type="primary" @click="saveEditedUser">确定</el-button>
        </span>
      </template>
    </el-dialog>
  </div>
</template>

<script setup>
import { ref } from 'vue';

// 模拟用户数据
const users = ref([
  { id: 1, name: '张三', email: 'zhangsan@example.com' },
  { id: 2, name: '李四', email: 'lisi@example.com' }
]);

// 添加用户对话框状态
const showAddUserDialog = ref(false);
// 新增用户对象
const newUser = ref({ name: '', email: '' });

// 编辑用户对话框状态
const showEditUserDialog = ref(false);
// 编辑中的用户对象
const editedUser = ref({ id: null, name: '', email: '' });

// 添加用户方法
const addUser = () => {
  const newId = users.value.length > 0 ? users.value[users.value.length - 1].id + 1 : 1;
  const user = { ...newUser.value, id: newId };
  users.value.push(user);
  newUser.value = { name: '', email: '' };
  showAddUserDialog.value = false;
};

// 编辑用户方法
const editUser = (user) => {
  editedUser.value = { ...user };
  showEditUserDialog.value = true;
};

// 保存编辑后的用户信息
const saveEditedUser = () => {
  const index = users.value.findIndex(u => u.id === editedUser.value.id);
  if (index !== -1) {
    users.value[index] = { ...editedUser.value };
  }
  showEditUserDialog.value = false;
};

// 删除用户方法
const deleteUser = (id) => {
  users.value = users.value.filter(user => user.id !== id);
};

// 添加调试函数
const handleAddUserClick = () => {
  showAddUserDialog.value = true;
};
</script>

<style scoped>
.el-form {
  display: block;
  min-height: 100px; /* 确保表单有最小高度 */
}
/* 样式可以根据需要进行调整 */
</style>